import re
import os

placeholders = []

for root, dirs, files in os.walk('/tmp/hwpx_work/template_contents'):
    for f in files:
        if f.endswith('.xml') or f.endswith('.hpf'):
            filepath = os.path.join(root, f)
            with open(filepath, 'r', encoding='utf-8') as file:
                content = file.read()
                matches = re.findall(r'\{\{[^}]+\}\}', content)
                if matches:
                    print(f"=== {filepath} ===")
                    for m in matches:
                        print(f"  {m}")
                    placeholders.extend(matches)

print("\n=== All unique placeholders ===")
for p in sorted(set(placeholders)):
    print(f"  {p}")
